def patch(live, backups):
    path = Path(live)
    if not path.is_file() or path.is_symlink():
        raise RuntimeError("Invalid live PHP path")
    original = path.read_bytes()
    updated = original
    for label, old, new in CHANGES:
        before, after = old.encode("utf-8"), new.encode("utf-8")
        if updated.count(after) == 1 and updated.count(before) == 0:
            print(label + ": installed")
        elif updated.count(before) == 1 and updated.count(after) == 0:
            updated = updated.replace(before, after, 1)
            print(label + ": updated")
        else:
            raise RuntimeError("Unrecognized live " + label +
                               " block; no file changes")
    if updated == original:
        print("MIRZA_RECEIPT_QUEUE_ALREADY_INSTALLED")
        return
    backup_dir = Path(backups)
    backup_dir.mkdir(parents=True, exist_ok=True, mode=0o700)
    backup = backup_dir / ("vpnapp.php.before-async-receipt-" +
        datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S-%f"))
    shutil.copy2(path, backup)
    fd, temp = tempfile.mkstemp(prefix=".vpnapp-async-",suffix=".php",dir=path.parent)
    try:
        with os.fdopen(fd,"wb") as out:
            out.write(updated)
        st = path.stat()
        shutil.copymode(path, temp)
        if os.geteuid() == 0:
            os.chown(temp, st.st_uid, st.st_gid)
        result=subprocess.run(["php","-l",temp],capture_output=True,text=True)
        if result.returncode:
            raise RuntimeError("PHP lint failed: " + result.stdout + result.stderr)
        os.replace(temp,path)
        print("BACKUP:",backup)
        print("MIRZA_ASYNC_RECEIPT_PATCHED")
    finally:
        if os.path.exists(temp): os.unlink(temp)

if __name__=="__main__":
    if len(sys.argv)!=2:
        print("Usage: sudo python3 patch_vpnapp_async_receipt.py /path/to/api/vpnapp.php")
        sys.exit(2)
    try:
        patch(sys.argv[1],"/root/mirza-backups")
    except (OSError, RuntimeError, UnicodeError) as err:
        print("ABORTED; existing file preserved:",err,file=sys.stderr)
        sys.exit(1)
